nginx./etc/nginx/sites-available/bnbu-staging-:
server {
    listen 80;
    listen [::]:80;
    server_name www.student.bnbusports.cn www.teacher.bnbusports.cn;
    location ^~ /.well-known/acme-challenge/ { root /var/lib/letsencrypt; try_files $uri =404; }
    location / { return 308 https://$host$request_uri; }
}
server {
    listen 443 ssl http2;
    listen [::]:443 ssl http2;
    server_name www.student.bnbusports.cn;
    ssl_certificate /etc/letsencrypt/live/bnbu-staging-hk/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/bnbu-staging-hk/privkey.pem;
    ssl_protocols TLSv1.2 TLSv1.3;
    server_tokens off;
    add_header X-Content-Type-Options nosniff always;
    add_header Referrer-Policy strict-origin-when-cross-origin always;
    add_header Cache-Control no-store always;
    root /opt/bnbu-sports-production/current/web;
    location = /runtime-config.js { try_files $uri =404; }
    location = / { return 302 /student/; }
    location /student/ { try_files $uri $uri/ =404; }
    location /api/v1/ {
        proxy_pass http://127.0.0.1:3000;
        proxy_set_header Host $host;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header X-Forwarded-For $remote_addr;
        client_max_body_size 2m;
        proxy_read_timeout 65s;
        access_log off;
    }
    location / { return 404; }
}
server {
    listen 443 ssl http2;
    listen [::]:443 ssl http2;
    server_name www.teacher.bnbusports.cn;
    ssl_certificate /etc/letsencrypt/live/bnbu-staging-hk/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/bnbu-staging-hk/privkey.pem;
    ssl_protocols TLSv1.2 TLSv1.3;
    server_tokens off;
    add_header X-Content-Type-Options nosniff always;
    add_header Referrer-Policy strict-origin-when-cross-origin always;
    add_header Cache-Control no-store always;
    location /api/v1/ {
        proxy_pass http://127.0.0.1:3000;
        proxy_set_header Host $host;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header X-Forwarded-For $remote_addr;
        client_max_body_size 2m;
        proxy_read_timeout 65s;
        access_log off;
    }
    location / {
        proxy_pass http://127.0.0.1:3100;
        proxy_set_header Host $host;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header X-Forwarded-For $remote_addr;
    }
}
